import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { EmisService } from 'src/app/services/emis/emis.service';
import { UserService } from 'src/app/services/emis/user.service';
import { UserSessionService } from 'src/app/services/usersession.service';

@Component({
  selector: 'app-my-arps',
  templateUrl: './my-arps.page.html',
  styleUrls: ['./my-arps.page.scss'],
})
export class MyArpsPage implements OnInit {
  arpList: any;
  teacher_id: any;
  block: any;

  constructor(public router:Router,private emisservice : EmisService,
    private usersessionService: UserSessionService,private userService: UserService) {
      this.teacher_id = this.usersessionService.teacher_id();
      
    }

  ngOnInit() {
    this.userService.getOoscUserDetails(this.teacher_id).subscribe(res => { 
      if (res.dataStatus) {
        this.block = res.result[0].block_id;
        if(this.block){
          this.initial()
        }
      }
    })
  }

  ionViewDidEnter() {
    if(this.block){
      this.initial()
    }
  }

  initial(){
    let data = {
      "BlkId": this.block
    }

    this.arpList = [];
    this.emisservice.ArpListBrte(data).subscribe(res => {
      if(res.dataStatus){
        this.arpList = res.result;
      }
    });
  }

  backBtn(){
    this.router.navigate(["/tabs/art-culture"])
  }
}
